CREATE TABLE IF NOT EXISTS branches (
  branch_id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  name VARCHAR(160) NOT NULL,
  address VARCHAR(255) NOT NULL,
  city VARCHAR(120) NOT NULL,
  province VARCHAR(120) NOT NULL,
  latitude DECIMAL(10,7) NOT NULL,
  longitude DECIMAL(10,7) NOT NULL,
  phone VARCHAR(40) DEFAULT NULL,
  schedule VARCHAR(180) DEFAULT NULL,
  takeout TINYINT(1) NOT NULL DEFAULT 1,
  pickup TINYINT(1) NOT NULL DEFAULT 1,
  status ENUM('open','closed','archived') NOT NULL DEFAULT 'open',
  created_by INT DEFAULT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (branch_id),
  KEY branches_status_name (status,name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS branch_staff (
  branch_id INT UNSIGNED NOT NULL,
  user_id INT NOT NULL,
  assigned_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (branch_id,user_id),
  KEY branch_staff_user (user_id),
  CONSTRAINT branch_staff_branch_fk FOREIGN KEY (branch_id) REFERENCES branches(branch_id) ON DELETE CASCADE,
  CONSTRAINT branch_staff_user_fk FOREIGN KEY (user_id) REFERENCES user_credentials(user_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

